class Solution {
    public int maxDistance(int[] colors){
        int answer=0,n=colors.length;
        for(int i=0;i<n;i++){
            if(colors[i]!=colors[0])answer=Math.max(answer,i);
            if(colors[i]!=colors[n-1])answer=Math.max(answer,n-1-i);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxDistance(colors:IntArray):Int{
        var answer=0;
        for(i in colors.indices){
            if(colors[i]!=colors[0])answer=maxOf(answer,i);
            if(colors[i]!=colors.last())answer=maxOf(answer,colors.lastIndex-i)
        };
        return answer
    }
}

